class Solution:
    def minutesToSpoil(self, grid: List[List[int]]) -> int:
        r, c = len(grid), len(grid[0]); g = [row[:] for row in grid]
        q = [(i, j) for i in range(r) for j in range(c) if g[i][j] == 2]
        fresh = sum(row.count(1) for row in g); t = 0
        while q and fresh:
            nq = []
            for i, j in q:
                for x, y in ((i+1,j),(i-1,j),(i,j+1),(i,j-1)):
                    if 0 <= x < r and 0 <= y < c and g[x][y] == 1:
                        g[x][y] = 2; fresh -= 1; nq.append((x, y))
            q = nq; t += 1
        return -1 if fresh else t

