function minutesToSpoil(grid) {
  const r = grid.length, c = grid[0].length, g = grid.map(x => x.slice());
  let q = [], fresh = 0, t = 0;
  for (let i = 0; i < r; i++) for (let j = 0; j < c; j++) { if (g[i][j] === 2) q.push([i, j]); if (g[i][j] === 1) fresh++; }
  while (q.length && fresh) {
    const nq = [];
    for (const [i, j] of q) for (const [x, y] of [[i+1,j],[i-1,j],[i,j+1],[i,j-1]])
      if (x >= 0 && x < r && y >= 0 && y < c && g[x][y] === 1) { g[x][y] = 2; fresh--; nq.push([x, y]); }
    q = nq; t++;
  }
  return fresh ? -1 : t;
}
